description:
A `TypedDict` only helps the type checker; data from a file still needs checking. Write:

```python
class Product(TypedDict):
    name: str
    price: float
    tags: list[str]
    discount: NotRequired[float]
```

and `parse_product(data: object) -> Product` that returns a **new** dictionary when `data` is valid, and raises `ValueError` with a message naming the problem otherwise:

- `data` must be a `dict`; `name` a non-empty `str`; `price` an `int` or `float` (not `bool`), at least 0, returned as `float`;
- `tags` a list of strings (may be empty);
- `discount`, if present, a number from 0 to 1; if missing it stays missing;
- any other key is an error.

solution.solution.py:
from typing import NotRequired, TypedDict


class Product(TypedDict):
    name: str
    price: float
    tags: list[str]
    discount: NotRequired[float]


def _number(value: object) -> bool:
    return isinstance(value, (int, float)) and not isinstance(value, bool)


def parse_product(data: object) -> Product:
    if not isinstance(data, dict):
        raise ValueError("a product must be an object")
    allowed = {"name", "price", "tags", "discount"}
    extra = set(data) - allowed
    if extra:
        raise ValueError(f"unknown key: {sorted(extra)[0]}")
    name = data.get("name")
    if not isinstance(name, str) or not name:
        raise ValueError("name must be a non-empty string")
    price = data.get("price")
    if not _number(price) or price < 0:
        raise ValueError("price must be a number of at least 0")
    tags = data.get("tags")
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        raise ValueError("tags must be a list of strings")
    product: Product = {"name": name, "price": float(price), "tags": list(tags)}
    if "discount" in data:
        d = data["discount"]
        if not _number(d) or not 0 <= d <= 1:
            raise ValueError("discount must be a number from 0 to 1")
        product["discount"] = float(d)
    return product

unitTests:
@test("a valid product comes back with a float price")
def _():
    p = parse_product({"name": "tea", "price": 3, "tags": ["drink"]})
    check_eq(p, {"name": "tea", "price": 3.0, "tags": ["drink"]})
    check(isinstance(p["price"], float))

@test("the result is a new dictionary")
def _():
    data = {"name": "tea", "price": 3.0, "tags": []}
    check(parse_product(data) is not data)

@test("discount kept when present")
def _():
    check_eq(parse_product({"name": "x", "price": 1.5, "tags": [], "discount": 0.25})["discount"], 0.25)

@test("bad values are refused")
def _():
    for bad in [[1], {"price": 1, "tags": []}, {"name": "", "price": 1, "tags": []},
                {"name": "x", "price": -1, "tags": []}, {"name": "x", "price": True, "tags": []},
                {"name": "x", "price": 1, "tags": "a"}, {"name": "x", "price": 1, "tags": [1]},
                {"name": "x", "price": 1, "tags": [], "discount": 2},
                {"name": "x", "price": 1, "tags": [], "colour": "red"}]:
        check_raises(ValueError, parse_product, bad)

